<?php namespace App\Jobs; use App\Services\MarketplaceEmail; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; class SendMarketplaceEmail implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=3; public int $timeout=60; public function __construct(public string $to,public string $subject,public string $html){} public function handle(MarketplaceEmail $email):void{$email->sendNow($this->to,$this->subject,$this->html);} }